bounded_host_request.command:
set -euo pipefail
n=gace-createvdobot-videobot-poll-1
test "$(docker inspect -f '{{.State.Running}}' "$n" 2>/dev/null)" = true || exit 61
docker exec -i "$n" node --input-type=module - <<'NODE'
import pg from 'pg';import {readFileSync} from 'node:fs';
const e=process.env,tokenPath=e.VIDEOBOT_TELEGRAM_TOKEN_FILE;
const pool=new pg.Pool({host:e.VIDEOBOT_DB_HOST,database:e.VIDEOBOT_DB_NAME,user:e.VIDEOBOT_DB_USER,password:readFileSync(e.VIDEOBOT_DB_PASSWORD_FILE,'utf8').trim(),max:1,connectionTimeoutMillis:4500});
try{
 const s=readFileSync('./src/telegram/stickerWizard.mjs','utf8');
 console.log('STICKER_LINK_START_HANDLER_LOADED='+String(s.includes("sticker_choose',stickerDraft:null,waiting:null")));
 const cursor=await pool.query("SELECT last_update_id,(EXTRACT(EPOCH FROM NOW()-updated_at))::int AS seconds_ago FROM videobot_poll_cursor WHERE consumer_id='createvdobot'");
 console.log('STICKER_POLL_CURSOR_EXISTS='+String(cursor.rowCount===1));
 console.log('STICKER_POLL_CURSOR_AGE_S='+String(cursor.rows[0]?.seconds_ago??'NO_CURSOR'));
 const grouped=await pool.query("SELECT COALESCE(state->>'screen','undefined') AS screen,COUNT(*)::int AS n FROM videobot_creator_sessions WHERE updated_at>NOW()-INTERVAL '6 HOURS' GROUP BY 1 ORDER BY n DESC");
 console.log('STICKER_RECENT_DM_SCREEN_COUNTS='+grouped.rows.map(r=>r.screen+':'+r.n).join(','));
 const p=await pool.query("SELECT s.state->>'screen' AS screen,s.state->'stickerPending'->>'status' AS pending,s.state->'stickerEditPending'->>'status' AS edit_pending,s.state->>'stickerDeferred' AS deferred,s.revision,(EXTRACT(EPOCH FROM NOW()-s.updated_at))::int AS age FROM videobot_sticker_products p LEFT JOIN videobot_creator_sessions s ON s.owner_user_id=p.seller_user_id WHERE p.product_id='sp_76f23430d1c29ca355960a95'");
 if(p.rowCount!==1)throw Error('STICKER_DM_SELLER_RECEIPT_NOT_FOUND');
 const row=p.rows[0];for(const key of ['screen','pending','edit_pending','deferred','revision','age'])console.log('STICKER_SELLER_DM_'+key.toUpperCase()+'='+String(row[key]??'NONE'));
}finally{await pool.end()}
NODE
printf 'STICKER_POLL_RECENT_HEALTH='
docker logs --since=90m "$n" 2>&1 | grep -E '^(CREATOR_DM_POLL_READY|CREATOR_DM_UPDATES_HANDLED|CREATOR_POLL_RUNTIME_FAILED)' | tail -n 8 | tr '\n' ';' || true
printf '\nSTICKER_READ_ONLY_DIAG=PASS\n'
